"""Fitted datasets for the Hosek-Wilkie sky and solar radiance models.

Transcribed from the authors' reference C release, version 1.4a
(https://cgg.mff.cuni.cz/projects/SkylightModelling/), file
``ArHosekSkyModelData_Spectral.h``. Redistributed under the licence in that
release: free use for research and non-commercial purposes, with the papers

    Lukas Hosek, Alexander Wilkie. An Analytic Model for Full Spectral Sky-Dome
    Radiance. ACM TOG 31(4), 2012.
    Lukas Hosek, Alexander Wilkie. Adding a Solar-Radiance Function to the
    Hosek-Wilkie Skylight Model. IEEE CG&A 33(3), 2013.

cited in any resulting publication.

Spectral rather than the model's own RGB fit: the 2013 solar model is
spectral-only, so this keeps sky and disc on one colour pipeline.

Shapes, matching the reference's indexing:

* ``SKY_PARAMS``     (11 wavelengths, 2 albedos, 10 turbidities, 6 control points, 9 parameters)
* ``SKY_RADIANCE``   (11, 2, 10, 6) -- overall radiance scale per configuration
* ``SUN_PARAMS``     (11, 10 turbidities, 45 elevation segments, 4 polynomial coefficients,
                      stored in descending power order)
* ``LIMB_DARKENING`` (11, 6) -- polynomial in the cosine of the position on the disc
"""

